#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>

template <int BLOCK_SIZE>
__global__ void layer_norm_fwd_kernel(
    const float* __restrict__ X,
    float* __restrict__ Y,
    const float* __restrict__ W,
    const float* __restrict__ B,
    float* __restrict__ Mean,
    float* __restrict__ Rstd,
    int stride,
    int N,
    float eps
) {
    int row = blockIdx.x;
    const float* x_row = X + row * stride;
    float* y_row = Y + row * stride;

    // Shared memory for reduction
    __shared__ float sdata[BLOCK_SIZE];

    // First pass: compute mean
    float sum = 0.0f;
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        sum += x_row[i];
    }
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Block reduction
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            sdata[threadIdx.x] += sdata[threadIdx.x + offset];
        }
        __syncthreads();
    }

    float mean = sdata[0] / N;

    // Second pass: compute variance
    sum = 0.0f;
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float diff = x_row[i] - mean;
        sum += diff * diff;
    }
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // Block reduction for variance
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            sdata[threadIdx.x] += sdata[threadIdx.x + offset];
        }
        __syncthreads();
    }

    float var = sdata[0] / N;
    float rstd = 1.0f / sqrtf(var + eps);

    // Store mean and rstd
    if (threadIdx.x == 0) {
        Mean[row] = mean;
        Rstd[row] = rstd;
    }

    // Third pass: normalize and apply weight/bias
    for (int i = threadIdx.x; i < N; i += blockDim.x) {
        float x = x_row[i];
        float x_hat = (x - mean) * rstd;
        float w = W[i];
        float b = B[i];
        y_row[i] = x_hat * w + b;
    }
}

// Launcher that selects block size based on N
void launch_layer_norm_kernel(
    const float* X, float* Y, const float* W, const float* B,
    float* Mean, float* Rstd, int stride, int N, float eps, int N_rows, cudaStream_t stream
) {
    // Choose block size as next power of 2, up to 1024
    int block_size = 1;
    while (block_size < N && block_size < 1024) block_size *= 2;

    if (block_size == 32) {
        layer_norm_fwd_kernel<32><<<N_rows, 32, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    } else if (block_size == 64) {
        layer_norm_fwd_kernel<64><<<N_rows, 64, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    } else if (block_size == 128) {
        layer_norm_fwd_kernel<128><<<N_rows, 128, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    } else if (block_size == 256) {
        layer_norm_fwd_kernel<256><<<N_rows, 256, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    } else if (block_size == 512) {
        layer_norm_fwd_kernel<512><<<N_rows, 512, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    } else {
        layer_norm_fwd_kernel<1024><<<N_rows, 1024, 0, stream>>>(X, Y, W, B, Mean, Rstd, stride, N, eps);
    }
}
